\set ON_ERROR_STOP on
BEGIN;
DO $$ BEGIN IF current_database() NOT LIKE 'acq_isolated_central_%' OR current_setting('aceleriq.isolated_tests',true) IS DISTINCT FROM 'on' THEN RAISE EXCEPTION 'isolated database required'; END IF; END $$;
SELECT no_plan();
INSERT INTO profiles(id) VALUES ('00000000-0000-0000-0000-000000000001'),('00000000-0000-0000-0000-000000000002'),('00000000-0000-0000-0000-000000000003'),('00000000-0000-0000-0000-000000000004');
INSERT INTO user_roles VALUES ('00000000-0000-0000-0000-000000000001','admin'),('00000000-0000-0000-0000-000000000002','manager'),('00000000-0000-0000-0000-000000000003','client'),('00000000-0000-0000-0000-000000000004','client');
UPDATE profiles SET plan_name='Synthetic complete plan',services_config='{"social":true,"traffic":true,"video":false,"pulse_history":[{"private":"synthetic"}]}' WHERE id='00000000-0000-0000-0000-000000000003';
INSERT INTO team_client_assignments VALUES ('00000000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000003');
INSERT INTO projects(id,client_id,status) VALUES ('10000000-0000-0000-0000-000000000003','00000000-0000-0000-0000-000000000003','active'),('10000000-0000-0000-0000-000000000004','00000000-0000-0000-0000-000000000004','active');
INSERT INTO client_dossiers(id,client_id,dossier_type,is_current,version,updated_at,content) VALUES ('20000000-0000-0000-0000-000000000003','00000000-0000-0000-0000-000000000003','contexto',true,1,now(),'{"private":"synthetic"}'),('20000000-0000-0000-0000-000000000004','00000000-0000-0000-0000-000000000004','contexto',true,1,now(),'{}');
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
INSERT INTO reports(id,client_id,project_id,title,summary,next_steps,metrics,period_start,period_end,status) SELECT ('30000000-0000-0000-0000-00000000000'||n)::uuid,('00000000-0000-0000-0000-00000000000'||n)::uuid,('10000000-0000-0000-0000-00000000000'||n)::uuid,'Synthetic review','Summary','Next',jsonb_build_object('ritual_type','weekly','central_review_source',central_review_source(('00000000-0000-0000-0000-00000000000'||n)::uuid)),'2026-09-07','2026-09-13','draft' FROM generate_series(3,4) n;
CREATE TEMP TABLE test_result(k text PRIMARY KEY,v jsonb);
GRANT ALL ON test_result TO authenticated;
SET LOCAL ROLE authenticated;
SELECT is((central_review_source('00000000-0000-0000-0000-000000000003')->>'dossier_version')::int,1,'source uses canonical persisted version');
SELECT is((SELECT count(*)::int FROM jsonb_object_keys(central_review_source('00000000-0000-0000-0000-000000000003'))),4,'source metadata only');
INSERT INTO test_result VALUES ('a',central_review_prepare('30000000-0000-0000-0000-000000000003',1,'{"channel":"portal","recipient":"00000000-0000-0000-0000-000000000003"}','prepare-a-1'));
INSERT INTO test_result VALUES ('b',central_review_prepare('30000000-0000-0000-0000-000000000004',1,'{"channel":"whatsapp","recipient":"synthetic"}','prepare-b-1'));
SELECT is((SELECT v->>'status' FROM test_result WHERE k='a'),'pendente','prepare pending');
SELECT is((SELECT v#>>'{payload,scope,plan_name}' FROM test_result WHERE k='a'),'Synthetic complete plan','contracted plan snapshot');
SELECT is((SELECT v#>'{payload,scope,service_keys}' FROM test_result WHERE k='a'),'["social","traffic"]'::jsonb,'scope exposes enabled service keys only');
SELECT is((SELECT count(*)::int FROM operator_approvals),2,'admin reads both central tenants');
SELECT is((SELECT operator_id FROM operator_approvals WHERE id=(SELECT (v->>'id')::uuid FROM test_result WHERE k='a')),NULL::uuid,'no false operator');
SELECT is(central_review_prepare('30000000-0000-0000-0000-000000000003',1,'{"channel":"portal","recipient":"00000000-0000-0000-0000-000000000003"}','prepare-a-1')->>'id',(SELECT v->>'id' FROM test_result WHERE k='a'),'prepare retry same id');
SELECT throws_ok($$SELECT central_review_prepare('30000000-0000-0000-0000-000000000003',1,'{"channel":"whatsapp","recipient":"changed"}','prepare-a-1')$$,'23505','CENTRAL_IDEMPOTENCY_CONFLICT','key cannot change destination');
SELECT throws_ok($$SELECT operator_approval_decidir((SELECT (v->>'id')::uuid FROM test_result WHERE k='a'),'aprovado',NULL)$$,'P0001','CENTRAL_USE_REVIEW_DECIDE','legacy cannot decide central');
SELECT throws_ok($$SELECT central_review_decide((SELECT (v->>'id')::uuid FROM test_result WHERE k='a'),'00000000-0000-0000-0000-000000000004',1,(SELECT v->>'payload_hash' FROM test_result WHERE k='a'),'aprovado',NULL,'wrong-client')$$,'42501','CENTRAL_CLIENT_MISMATCH','client CAS');
INSERT INTO test_result SELECT 'comment',central_review_decide((SELECT (v->>'id')::uuid FROM test_result WHERE k='a'),'00000000-0000-0000-0000-000000000003',1,(SELECT v->>'payload_hash' FROM test_result WHERE k='a'),'comentario','Review comment','comment-a-1');
SELECT is((SELECT v->>'status' FROM test_result WHERE k='comment'),'pendente','comment does not decide');
INSERT INTO test_result SELECT 'decision',central_review_decide((SELECT (v->>'id')::uuid FROM test_result WHERE k='a'),'00000000-0000-0000-0000-000000000003',1,(SELECT v->>'payload_hash' FROM test_result WHERE k='a'),'aprovado','Approved synthetic','decision-a-1');
SELECT is((SELECT v->>'status' FROM test_result WHERE k='decision'),'aprovado','admin approves snapshot');
SELECT is(central_review_decide((SELECT (v->>'id')::uuid FROM test_result WHERE k='a'),'00000000-0000-0000-0000-000000000003',1,(SELECT v->>'payload_hash' FROM test_result WHERE k='a'),'comentario','Historical approved comment','approved-comment-a')->>'status','aprovado','comment preserves a historical approval decision');
SELECT is(central_review_decide((SELECT (v->>'id')::uuid FROM test_result WHERE k='a'),'00000000-0000-0000-0000-000000000003',1,(SELECT v->>'payload_hash' FROM test_result WHERE k='a'),'aprovado','Approved synthetic','decision-a-1'),(SELECT v FROM test_result WHERE k='decision'),'decision retry exact result');
SELECT throws_ok($$SELECT central_review_decide((SELECT (v->>'id')::uuid FROM test_result WHERE k='a'),'00000000-0000-0000-0000-000000000003',1,(SELECT v->>'payload_hash' FROM test_result WHERE k='a'),'rejeitado','Changed decision','decision-a-2')$$,'40001','CENTRAL_ALREADY_DECIDED','second decision cannot replace first');
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',true);
SELECT is((SELECT count(*)::int FROM operator_approvals),0,'staff cannot read central snapshot');
SELECT is((SELECT count(*)::int FROM central_review_events),0,'staff cannot read review comments and audit');
SELECT is((SELECT count(*)::int FROM central_review_dispatches),0,'staff cannot read central delivery state');
SELECT lives_ok($$SELECT central_review_source('00000000-0000-0000-0000-000000000003')$$,'assigned staff source');
SELECT throws_ok($$SELECT central_review_source('00000000-0000-0000-0000-000000000004')$$,'42501','CENTRAL_CLIENT_SCOPE_DENIED','cross tenant source denied');
SELECT throws_ok($$SELECT central_review_prepare('30000000-0000-0000-0000-000000000003',1,'{"channel":"portal","recipient":"x"}','staff-denied')$$,'42501','CENTRAL_ADMIN_REQUIRED','staff cannot prepare');
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000003',true);
SELECT is((SELECT count(*)::int FROM operator_approvals),0,'client cannot read snapshot');
SELECT throws_ok($$SELECT central_review_source('00000000-0000-0000-0000-000000000003')$$,'42501','CENTRAL_CLIENT_SCOPE_DENIED','client cannot query private source');
RESET ROLE;
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
SELECT throws_ok($$UPDATE operator_approvals SET destino='mutated' WHERE origin='central'$$,'P0001','CENTRAL_SNAPSHOT_IMMUTABLE','destination frozen');
UPDATE reports SET summary='Revision two' WHERE id='30000000-0000-0000-0000-000000000003';
SELECT is((SELECT review_version FROM reports WHERE id='30000000-0000-0000-0000-000000000003'),2,'report content increments version');
SELECT is((SELECT status FROM operator_approvals WHERE id=(SELECT (v->>'id')::uuid FROM test_result WHERE k='a')),'expirado','report change invalidates own approval');
SELECT is(central_review_decide((SELECT (v->>'id')::uuid FROM test_result WHERE k='a'),'00000000-0000-0000-0000-000000000003',1,(SELECT v->>'payload_hash' FROM test_result WHERE k='a'),'comentario','Context for the previous version','old-version-comment-a')->>'status','expirado','comment on old snapshot does not revive an invalidated request');
SELECT throws_ok($$SELECT central_review_decide((SELECT (v->>'id')::uuid FROM test_result WHERE k='a'),'00000000-0000-0000-0000-000000000004',1,(SELECT v->>'payload_hash' FROM test_result WHERE k='a'),'comentario','Wrong client','old-version-wrong-client')$$,'42501','CENTRAL_CLIENT_MISMATCH','historical comment cannot cross clients');
SELECT throws_ok($$SELECT central_review_decide((SELECT (v->>'id')::uuid FROM test_result WHERE k='a'),'00000000-0000-0000-0000-000000000003',2,(SELECT v->>'payload_hash' FROM test_result WHERE k='a'),'comentario','Wrong snapshot version','old-version-wrong-version')$$,'40001','CENTRAL_REPORT_VERSION_CONFLICT','historical comment still binds exact snapshot version');
SELECT is((SELECT status FROM operator_approvals WHERE id=(SELECT (v->>'id')::uuid FROM test_result WHERE k='b')),'pendente','other tenant unchanged');
SELECT is((SELECT count(*)::int FROM operator_approvals),2,'history preserved');
UPDATE client_dossiers SET version=2,updated_at=now()+interval '1 second' WHERE client_id='00000000-0000-0000-0000-000000000004';
SELECT throws_ok($$SELECT central_review_decide((SELECT (v->>'id')::uuid FROM test_result WHERE k='b'),'00000000-0000-0000-0000-000000000004',1,(SELECT v->>'payload_hash' FROM test_result WHERE k='b'),'aprovado',NULL,'stale-b-source')$$,'40001','CENTRAL_SOURCE_STALE','changed dossier invalidates decision');
SELECT is((SELECT count(*)::int FROM central_review_dispatches WHERE status IN('enviado','confirmado')),0,'no transport or delivery invented');
SELECT ok(NOT has_function_privilege('anon','public.central_review_prepare(uuid,integer,jsonb,text)','execute'),'anonymous prepare has no EXECUTE grant');
SELECT ok(NOT has_function_privilege('anon','public.central_review_decide(uuid,uuid,integer,text,text,text,text)','execute'),'anonymous decide has no EXECUTE grant');
SELECT throws_ok($$SELECT central_review_prepare('30000000-0000-0000-0000-000000000003',2,'{"channel":"portal","recipient":"00000000-0000-0000-0000-000000000004"}','wrong-portal-client')$$,'42501','CENTRAL_PORTAL_RECIPIENT_MISMATCH','portal destination cannot be another client');
SELECT throws_ok($$SELECT central_review_decide((SELECT (v->>'id')::uuid FROM test_result WHERE k='b'),'00000000-0000-0000-0000-000000000004',1,(SELECT v->>'payload_hash' FROM test_result WHERE k='b'),'alteracoes_pedidas',' ','no-adjust-comment')$$,'P0001','CENTRAL_COMMENT_REQUIRED','adjustment requires actionable comment');
UPDATE reports SET next_steps='' WHERE id='30000000-0000-0000-0000-000000000003';
SELECT throws_ok($$SELECT central_review_prepare('30000000-0000-0000-0000-000000000003',3,'{"channel":"portal","recipient":"00000000-0000-0000-0000-000000000003"}','missing-next-step')$$,'P0001','CENTRAL_NEXT_STEPS_REQUIRED','missing next step blocks backend preparation');
UPDATE reports SET summary='' WHERE id='30000000-0000-0000-0000-000000000003';
SELECT throws_ok($$SELECT central_review_prepare('30000000-0000-0000-0000-000000000003',4,'{"channel":"portal","recipient":"00000000-0000-0000-0000-000000000003"}','missing-summary')$$,'P0001','CENTRAL_SUMMARY_REQUIRED','missing message blocks backend preparation');
UPDATE reports SET summary='Complete review',next_steps='Explicit next task' WHERE id='30000000-0000-0000-0000-000000000003';
INSERT INTO test_result VALUES ('source-before',central_review_source('00000000-0000-0000-0000-000000000003'));
INSERT INTO client_dossiers(client_id,dossier_type,is_current,version,updated_at,content) VALUES ('00000000-0000-0000-0000-000000000003','brand',true,1,now(),'Supplemental context');
SELECT isnt(central_review_source('00000000-0000-0000-0000-000000000003')->>'scope_hash',(SELECT v->>'scope_hash' FROM test_result WHERE k='source-before'),'supplemental dossier changes source hash');
SELECT is(central_review_source('00000000-0000-0000-0000-000000000003')->>'dossier_id',(SELECT v->>'dossier_id' FROM test_result WHERE k='source-before'),'supplement does not replace canonical context');
SELECT throws_ok($$SELECT central_review_prepare('30000000-0000-0000-0000-000000000003',5,'{"channel":"portal","recipient":"00000000-0000-0000-0000-000000000003"}','changed-supplement')$$,'40001','CENTRAL_SOURCE_STALE','supplemental context prevents stale generation approval');
INSERT INTO test_result VALUES ('source-project',central_review_source('00000000-0000-0000-0000-000000000003'));
UPDATE projects SET scope='Changed contracted front' WHERE client_id='00000000-0000-0000-0000-000000000003';
SELECT isnt(central_review_source('00000000-0000-0000-0000-000000000003')->>'scope_hash',(SELECT v->>'scope_hash' FROM test_result WHERE k='source-project'),'project scope changes source hash');
UPDATE reports SET status='published' WHERE id='30000000-0000-0000-0000-000000000003';
SELECT throws_ok($$UPDATE reports SET summary='Forbidden published change' WHERE id='30000000-0000-0000-0000-000000000003'$$,'P0001','published reports are immutable','existing production guard preserves published immutability');
SELECT is((SELECT review_version FROM reports WHERE id='30000000-0000-0000-0000-000000000003'),5,'failed published edit rolls back version change');
INSERT INTO internal_operators(id) VALUES ('40000000-0000-0000-0000-000000000001');
INSERT INTO operator_approvals(id,operator_id,action_kind,o_que,por_que,valid_until)
 VALUES ('50000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000001','enviar_mensagem','Expired synthetic','Expiry regression',now()-interval '1 minute');
SELECT throws_ok($$SELECT operator_approval_decidir('50000000-0000-0000-0000-000000000001','aprovado',NULL)$$,'P0001','CENTRAL_APPROVAL_EXPIRED','legacy approval now enforces expiry');
SELECT is((SELECT status FROM operator_approvals WHERE id='50000000-0000-0000-0000-000000000001'),'pendente','expired legacy attempt preserves history');
SELECT * FROM finish();
ROLLBACK;
